import tomlkit
from tomlkit.parser import Parser
from tomlkit.exceptions import UnexpectedCharError


def parse_key_value(src: str) -> tuple[str, str | int | float | bool | list | dict]:
    """Parse a key-value pair from a string. src: a string containing a key-value pair, e.g. 'foo = 1' -> ('foo', 1)"""
    try:
        parser = Parser(src)
        k, v = parser._parse_key_value(parse_comment=True)
        if not parser.end():
            raise parser.parse_error(UnexpectedCharError, char=parser._current)

        # Convert the value to appropriate Python type and then to string for consistency
        value = v.value if hasattr(v, 'value') else v
        return str(k), str(value)
    except Exception as e:
        raise ValueError(f"Failed to parse key-value pair: {src!r}") from e

